  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 17, $j$5.1 Conversation and Conflict$j$, $j${"readings": [{"title": "Matthew 18 (King James Version)", "url": "/portal/bible/Matthew/18"}], "body": "Most of our communication happens in ordinary conversation, and it shapes our friendships, families and futures. Matthew 18:15 gives a pattern for handling conflict: Moreover if thy brother shall trespass against thee, go and tell him his fault between thee and him alone: if he shall hear thee, thou hast gained thy brother. The goal of hard conversation is to win a person, not to win an argument.\n\nGood conversation has a few habits. Start with a greeting and use the person's name. Ask open questions, which need more than a yes or no, such as, What did you enjoy most about the trip? Listen to the answer and ask a follow up. Share something of yourself in return. Take turns, so that the talk is not a monologue. Keep your phone out of sight. Use a friendly tone and appropriate humor. End kindly.\n\nConflict is a normal part of life, since people have different needs, views and feelings. It becomes harmful when handled badly. Common unhelpful styles include avoiding the problem, attacking the other person, giving in every time and using sarcasm or silence as punishment. A better approach is to work together on the problem. Choose a good time and place and not a public moment or a moment of anger. Take a breath and calm down first. Use I statements, which describe your feeling and the issue without blaming, such as, I feel worried when the project is late, instead of, You never do your part. Describe the behavior, not the person's character. Listen to the other side and paraphrase it. Look for what you agree on and for the real need behind the conflict. Brainstorm several solutions and choose one that is fair. Agree on what each person will do. If you were wrong, apologize sincerely and name what you did, without adding but or excuses.\n\nSome situations need a trusted adult, such as a parent, pastor or teacher, especially when there is bullying, a threat to safety or a conflict that is not getting better. Asking for help is a sign of wisdom. Romans 12:18 says, If it be possible, as much as lieth in you, live peaceably with all men. Proverbs 15:1 reminds us, A soft answer turneth away wrath.\n\nYour task: (1) List four habits of good conversation. (2) Write an I statement for a conflict. (3) Describe the steps in Matthew 18:15 and when to seek an adult.\n\nFlorida standards: SPC.912.C.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SPC.912.C", "script": "Welcome back. Listen, Matthew 18:15 says, Moreover if thy brother shall trespass against thee, go and tell him his fault between thee and him alone: if he shall hear thee, thou hast gained thy brother. The goal of a hard conversation is to win a person, not to win an argument.\n\nNow watch this. Good conversation uses a greeting and the person's name, open questions, follow ups, sharing, taking turns, no phone and a friendly tone.\n\nConflict is normal. Unhelpful styles are avoiding, attacking, always giving in and sarcasm. A better way is to work together. Choose a good time and place. Calm down first. Use I statements, like, I feel worried when the project is late. Describe the behavior, not the person's character. Listen and paraphrase. Find the real need. Brainstorm solutions. Agree on actions. If you were wrong, apologize without excuses.\n\nSome situations need a trusted adult, especially bullying, a threat to safety or a conflict that is not improving. Asking for help is wise. Romans 12:18 says, If it be possible, as much as lieth in you, live peaceably with all men.\n\nYour task is to list conversation habits, write an I statement and describe the steps in Matthew 18. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$5.1 Conversation and Conflict$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 18, $j$5.2 Group Discussion, Leadership and Meetings$j$, $j${"readings": [{"title": "Proverbs 11 (King James Version)", "url": "/portal/bible/Proverbs/11"}], "body": "Much of life's important work is done in groups, such as committees, teams, clubs, church boards and families. Proverbs 11:14 says, Where no counsel is, the people fall: but in the multitude of counsellors there is safety. Groups can make better decisions than one person when members listen, share and respect each other.\n\nA small group discussion works best with clear roles. A leader keeps the group on the task and the time, invites everyone to speak and helps summarize. A recorder takes notes of ideas and decisions. A timekeeper watches the clock. Members come prepared, share ideas, listen and support the group's goal. Good members avoid dominating the talk, side conversations and put downs.\n\nGroups often follow steps for solving a problem. First, define the problem in a clear question. Second, analyze the causes and effects. Third, set criteria, which are the standards a good solution must meet, such as cost, time and fairness. Fourth, brainstorm solutions without judging them. Fifth, evaluate the options against the criteria. Sixth, choose the best solution and plan how to carry it out. Finally, review the results later.\n\nGroups develop in stages, often called forming, storming, norming and performing. At first members get to know each other. Then disagreements appear. As they settle on rules and trust, the group begins to work well. Conflict in the storming stage is normal and can be handled with respect.\n\nLeadership in a group is service. A leader sets a vision, listens, shares credit and shares the work. Styles vary: some leaders direct, some involve everyone in decisions and some give freedom. Good leaders choose the style that fits the group and the task. Jesus said in Mark 10:43, whosoever will be great among you, shall be your minister.\n\nFormal meetings often use parliamentary procedure, a set of rules based on Robert's Rules of Order, first published in 1876 by Henry Martyn Robert. These rules protect the rights of the majority and the minority. A member makes a motion, which is a proposal for the group to act on. Another member seconds it. The chair states the motion and the group debates it. Then the group votes, and the chair announces the result. Rules about turns to speak keep the meeting fair and orderly. An agenda lists the order of business, and minutes are the written record of what was decided.\n\nYour task: (1) Name three roles in a small group and describe each. (2) List the steps of group problem solving. (3) Describe how a motion moves through a meeting.\n\nFlorida standards: SPC.912.C.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SPC.912.C", "script": "Welcome back. Listen, Proverbs 11:14 says, Where no counsel is, the people fall: but in the multitude of counsellors there is safety. Groups can decide better than one person when members listen, share and respect each other.\n\nNow watch this. A small group needs roles. The leader keeps the group on task and invites everyone to speak. The recorder takes notes. The timekeeper watches the clock. Members come prepared and avoid dominating, side talk and put downs.\n\nGroup problem solving has steps. Define the problem. Analyze causes. Set criteria. Brainstorm without judging. Evaluate options. Choose and plan. Review later.\n\nGroups pass through forming, storming, norming and performing. Conflict in storming is normal.\n\nLeadership is service. Jesus said in Mark 10:43, whosoever will be great among you, shall be your minister.\n\nFormal meetings use parliamentary procedure from Robert's Rules of Order, first published in 1876. A member makes a motion. Another seconds. The chair states it. The group debates. The group votes. The chair announces the result. An agenda lists the business and minutes record what was decided.\n\nYour task is to name group roles, list problem solving steps and describe a motion. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$5.2 Group Discussion, Leadership and Meetings$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 19, $j$5.3 Interviews and Professional Communication$j$, $j${"readings": [{"title": "Proverbs 22 (King James Version)", "url": "/portal/bible/Proverbs/22"}], "body": "A job or college interview is a speaking skill that can shape your future. Proverbs 22:29 says, Seest thou a man diligent in his business? he shall stand before kings; he shall not stand before mean men. Diligence and preparation make a person ready to stand before others with confidence.\n\nBefore an interview, research the organization. Learn what it does, its mission and the job or program. Review your own strengths, experiences and goals. Prepare answers to common questions, such as, Tell me about yourself, Why do you want this job, What are your strengths and weaknesses, and Tell me about a time you solved a problem. A helpful tool for describing an experience is the STAR method: Situation, Task, Action and Result. Describe the situation, your task, the action you took and the result you achieved. Prepare two or three questions of your own, such as, What does a successful first month look like? Practice aloud with a parent or mentor.\n\nOn the day of the interview, dress neatly, arrive 10 to 15 minutes early and turn off your phone. Greet the interviewer with eye contact, a smile and a firm handshake. Sit upright. Listen carefully and answer the question that was asked. Be honest, positive and specific. Speak well of past teachers and employers. Do not exaggerate or claim skills you do not have. Show enthusiasm and humility. At the end, thank the interviewer and ask about next steps. Send a short thank you note or email within a day.\n\nProfessional communication also includes emails and phone calls. A good email has a clear subject line, a polite greeting, a short message with the main point first, correct spelling and grammar, and a courteous closing with your name and contact information. Do not use all capital letters, slang or too many exclamation points. Read it twice before sending. Reply promptly, usually within one or two business days. On the phone, state your name and purpose, speak clearly, and take notes. Keep your voice mail greeting and your email address professional.\n\nAppropriate topics matter. Employers cannot lawfully ask about certain private matters such as religion, age or family plans in most hiring decisions, and a candidate can politely steer the answer toward the job's requirements.\n\nYour task: (1) Write a STAR answer to a question about a time you solved a problem. (2) List five steps for interview day. (3) Write a short professional email requesting information.\n\nFlorida standards: SPC.912.C.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SPC.912.C", "script": "Welcome back. Listen, Proverbs 22:29 says, Seest thou a man diligent in his business? he shall stand before kings; he shall not stand before mean men. Diligence and preparation make a person ready to stand before others.\n\nNow watch this. Before an interview, research the organization and review your strengths. Prepare answers to common questions. Use the STAR method: situation, task, action and result. Prepare two or three questions of your own. Practice aloud.\n\nOn interview day dress neatly, arrive 10 to 15 minutes early and turn off your phone. Greet with eye contact, a smile and a firm handshake. Answer the question asked. Be honest, positive and specific. Do not exaggerate. Thank the interviewer and send a short thank you note within a day.\n\nA good email has a clear subject line, a polite greeting, the main point first, correct spelling and a courteous closing with your name. No all capital letters or slang. Reply within one or two business days. On the phone, state your name and purpose and take notes. Keep your email address and voice mail greeting professional.\n\nYour task is to write a STAR answer, list interview day steps and write a professional email. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$5.3 Interviews and Professional Communication$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 20, $j$5.4 Digital and Media Communication$j$, $j${"readings": [{"title": "Philippians 4 (King James Version)", "url": "/portal/bible/Philippians/4"}], "body": "Much of our communication now travels through screens. Philippians 4:8 says, Finally, brethren, whatsoever things are true, whatsoever things are honest, whatsoever things are just, whatsoever things are pure, whatsoever things are lovely, whatsoever things are of good report; if there be any virtue, and if there be any praise, think on these things. This verse gives a filter for what we read, share and post.\n\nDigital communication includes text messages, email, social media, video calls, online posts and comments. These channels are fast and reach far, but they also remove tone of voice and facial expression, so messages are easily misunderstood. Before sending, reread and ask whether the message is true, kind and necessary. Emojis and clear wording can help, but sarcasm often fails in text. Do not send messages in anger. Wait before you post or reply.\n\nDigital citizenship means acting with respect and responsibility online. Treat people as you would face to face. Protect your privacy and the privacy of others: do not post addresses, phone numbers, school schedules, passwords or private photos. Remember that what is posted can last, since screenshots can be saved and shared, and a digital footprint can be seen by colleges and employers. Only share an image or message of another person with permission. Be careful with strangers online, never meet an online contact alone, and tell a trusted adult if someone makes you uncomfortable. Cyberbullying, which means using technology to harass, threaten or shame someone, is harmful and may break school rules and the law. If you are targeted, do not respond in kind. Save the evidence, block the person and tell a parent, teacher or pastor.\n\nMedia literacy is the ability to understand and judge what we see and hear. Ask who made the message, what the purpose is, who benefits, what is left out, and whether the claims can be confirmed by reliable sources. Be careful with headlines, edited images and videos, and with posts that stir strong emotion, since they are often designed to be shared. Artificial intelligence tools can now make realistic fake images, voices and text. Check the source before you believe or share. Respect copyright by crediting creators and not copying their work.\n\nDigital tools can also serve ministry and service, such as sharing encouragement, announcing events and recording speeches. Colossians 3:17 says, whatsoever ye do in word or deed, do all in the name of the Lord Jesus.\n\nYour task: (1) List five rules of digital citizenship. (2) Ask five media literacy questions about a post. (3) Explain what to do if you are cyberbullied.\n\nFlorida standards: SPC.912.C.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "SPC.912.C", "script": "Welcome back. Listen, Philippians 4:8 says, Finally, brethren, whatsoever things are true, whatsoever things are honest, whatsoever things are just, whatsoever things are pure, whatsoever things are lovely, whatsoever things are of good report; if there be any virtue, and if there be any praise, think on these things. That verse gives us a filter for what we read, share and post.\n\nNow watch this. Digital messages are fast but lose tone of voice and expression. Reread before sending. Ask, is it true, kind and necessary? Sarcasm often fails in text. Do not send in anger.\n\nDigital citizenship means respect and responsibility. Protect your privacy and others'. Do not post addresses, phone numbers, schedules, passwords or private photos. Posts can last. Share images of others only with permission. Never meet an online contact alone. Tell a trusted adult if someone makes you uncomfortable. If you are bullied online, do not respond in kind, save the evidence, block the person and tell an adult.\n\nMedia literacy asks who made it, why, who benefits, what is left out and can it be confirmed. AI can make realistic fake images, voices and text. Check the source. Respect copyright.\n\nColossians 3:17 says, whatsoever ye do in word or deed, do all in the name of the Lord Jesus.\n\nYour task is to list digital citizenship rules, ask media literacy questions and explain what to do about cyberbullying. Take the four question check. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$5.4 Digital and Media Communication$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 5, $j$Assessment 5: Conversation, Groups, Interviews and Digital Communication$j$, $j${"prompt": "Write a report of at least 250 words, with sample work, on communication beyond the podium. Use complete sentences and label each part. Matthew 18:15 says, Moreover if thy brother shall trespass against thee, go and tell him his fault between thee and him alone: if he shall hear thee, thou hast gained thy brother.\n\nPart 1: List five habits of good conversation. Describe a conflict (real or made up, with no names) and write an I statement for it. Describe the steps you would take to settle it, including when to ask a trusted adult.\nPart 2: Name and describe three roles in a small group. List the steps of group problem solving. Explain the steps of a motion in a meeting using parliamentary procedure.\nPart 3: Write a STAR answer to the question, Tell me about a time you solved a problem. List five steps you would take on the day of an interview.\nPart 4: Write a short professional email asking for information about a program or job. Include a subject line, greeting, body and closing.\nPart 5: List five rules of digital citizenship and five media literacy questions. Explain how Philippians 4:8 and Colossians 3:17 guide what we say and share online.", "rubric": "100 points. Part 1: 20 points. Part 2: 20 points. Part 3: 20 points. Part 4: 15 points. Part 5: 20 points. Complete sentences and conventions: 5 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 5: Conversation, Groups, Interviews and Digital Communication$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 5, $j$Discussion 5: Peacemakers and Good Citizens$j$, $j${"prompt": "Write a post of at least 120 words that (1) describes a time when you saw a conflict handled well or poorly, with no names, (2) explains in your own words how an I statement or the steps in Matthew 18:15 could help, (3) explains how a believer should communicate online and in a job interview, and (4) connects your answer to Matthew 18:15, Proverbs 22:29 or Philippians 4:8. Then write a respectful reply of at least 40 words to another student's post, or answer this question: How can a believer be a peacemaker without avoiding hard conversations? Keep your tone kind and respectful of other views."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 5: Peacemakers and Good Citizens$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 21, $j$Check 5.1: Conversation and Conflict$j$, $j${"questions": [{"q": "An open question is one that:", "options": ["Has no answer", "Needs more than a yes or no answer", "Can only be answered yes or no", "Is rude"]}, {"q": "Which is an I statement?", "options": ["I feel worried when the project is late.", "You never do your part.", "Everyone hates you.", "You are lazy."]}, {"q": "The goal of a hard conversation, according to Matthew 18:15, is to:", "options": ["Avoid him", "Win the argument", "Embarrass him", "Gain your brother"]}, {"q": "When should a student bring in a trusted adult?", "options": ["Only after a fight", "Never", "Only on holidays", "When there is bullying or a threat to safety"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.1: Conversation and Conflict$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,0,3,3}'::int[], array[$j$Open questions invite longer answers.$j$,$j$I statements describe feelings without blame.$j$,$j$The aim is restoration of the relationship.$j$,$j$Safety and serious problems need adult help.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.1: Conversation and Conflict$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 22, $j$Check 5.2: Group Discussion, Leadership and Meetings$j$, $j${"questions": [{"q": "A formal proposal for a group to act on is a:", "options": ["Agenda", "Motion", "Minute", "Gavel"]}, {"q": "Standards that a good solution must meet, such as cost and fairness, are:", "options": ["Noise", "Minutes", "Feedback", "Criteria"]}, {"q": "The written record of a meeting is the:", "options": ["Agenda", "Minutes", "Second", "Motion"]}, {"q": "According to Mark 10:43, greatness in a group comes through:", "options": ["Talking the most", "Avoiding work", "Serving others", "Controlling others"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.2: Group Discussion, Leadership and Meetings$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,3,1,2}'::int[], array[$j$A motion begins the decision process.$j$,$j$Criteria guide the evaluation of solutions.$j$,$j$Minutes record the decisions.$j$,$j$Jesus taught that the great serve.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.2: Group Discussion, Leadership and Meetings$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 23, $j$Check 5.3: Interviews and Professional Communication$j$, $j${"questions": [{"q": "In the STAR method, the letter R stands for:", "options": ["Result", "Reason", "Reply", "Rule"]}, {"q": "A good time to arrive for an interview is:", "options": ["30 minutes late", "The next day", "Exactly on time with no margin", "10 to 15 minutes early"]}, {"q": "A professional email should have:", "options": ["No name", "A clear subject line and polite greeting", "All capital letters", "Slang"]}, {"q": "After an interview, a candidate should:", "options": ["Send a short thank you note within a day", "Argue the decision", "Do nothing", "Post about the interviewer"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.3: Interviews and Professional Communication$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,3,1,0}'::int[], array[$j$Result tells what happened because of your action.$j$,$j$Early arrival shows respect and allows calm.$j$,$j$Clear and courteous messages show respect.$j$,$j$A thank you note leaves a good impression.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.3: Interviews and Professional Communication$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 24, $j$Check 5.4: Digital and Media Communication$j$, $j${"questions": [{"q": "Before sending a message, a wise communicator asks whether it is:", "options": ["True, kind and necessary", "Long", "Anonymous", "Funny only"]}, {"q": "Which should never be posted publicly?", "options": ["A Bible verse", "Your home address and passwords", "A thank you to a teacher", "A school club announcement"]}, {"q": "If someone cyberbullies you, you should:", "options": ["Spread the message", "Save the evidence, block them and tell a trusted adult", "Delete everything and say nothing", "Reply with insults"]}, {"q": "Media literacy includes asking:", "options": ["How many colors does it have?", "Is it long?", "Is it popular only?", "Who made this message and what is its purpose?"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.4: Digital and Media Communication$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,1,1,3}'::int[], array[$j$These questions filter careless words.$j$,$j$Private information can put you at risk.$j$,$j$Document it and get help.$j$,$j$Knowing the source and purpose helps judge a message.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 5.4: Digital and Media Communication$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 25, $j$Unit Quiz 5: Conversation, Groups, Interviews and Digital Communication$j$, $j${"questions": [{"q": "Asking, What did you enjoy most about the trip? is an example of:", "options": ["An open question", "A put down", "A closed question", "A motion"]}, {"q": "Which response style works best in conflict?", "options": ["Giving the silent treatment", "Working together on the problem", "Attacking the other person", "Using sarcasm"]}, {"q": "In parliamentary procedure, after a motion is made, the next step is a:", "options": ["Vote", "Break", "Second", "Adjournment"]}, {"q": "The set of rules for formal meetings based on Henry Martyn Robert's work is:", "options": ["The STAR method", "The CRAAP list", "Robert's Rules of Order", "The Gettysburg rules"]}, {"q": "The S in STAR stands for:", "options": ["Slide", "Source", "Speech", "Situation"]}, {"q": "When writing a professional email, you should:", "options": ["Leave off a subject line", "Put the main point first and use correct spelling", "Use all capital letters", "Use slang"]}, {"q": "Online, a good rule is to:", "options": ["Think before posting because posts can last", "Post in anger", "Meet strangers alone", "Share passwords"]}, {"q": "Philippians 4:8 gives a filter for what we think about and share. It includes things that are:", "options": ["Shocking and false", "True, honest, just, pure and lovely", "Private and secret", "Unkind but funny"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 5: Conversation, Groups, Interviews and Digital Communication$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,1,2,2,3,1,0,1}'::int[], array[$j$It invites a full answer.$j$,$j$Collaboration solves problems and keeps relationships.$j$,$j$A second shows that another member wants to discuss it.$j$,$j$It was first published in 1876.$j$,$j$STAR is Situation, Task, Action, Result.$j$,$j$Clarity and courtesy matter.$j$,$j$A digital footprint can be seen later.$j$,$j$The verse lists qualities worthy of our attention.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 5: Conversation, Groups, Interviews and Digital Communication$j$ on conflict (item_id) do nothing;
